    if head == nil || head.Next == nil {
        return head
    }

    newHead := reverseRecursive(head.Next)
    head.Next.Next = head   // Revertir el enlace
    head.Next = nil         // Cortar enlace anterior
    return newHead
}
```

## Ejemplo completo

```go
